        ch(2, "¿Qué significa?", "das Vorstellungsgespräch", "la entrevista de trabajo", ["la entrevista de trabajo", "la presentación de un producto", "la carta de presentación"], "*sich vorstellen* = presentarse."),
        cz(2, "Escribí el adjetivo con su terminación.", "Wir bieten ___ Arbeitszeiten. (flexibel)", "flexible", note="Plural sin artículo: *-e*. *flexibel* pierde la *e*: *flexible*."),
